    // Native copy lookup; the current document locale comes from DesktopLocale.
    public static string ForLanguage(string key, string language)
    {
        if (language == "en") return key switch
        {
            nameof(Recover) => "Recover access",
            nameof(Restart) => "Restart backend\u2026",
            nameof(Revoke) => "Revoke access",
            nameof(BackendUnavailable) => "Backend unavailable. The window and drafts are preserved; recover through the title-bar icon menu.",
            nameof(RecoveryReady) => "Access restored. Select \"Check session again\" in the interface; drafts are preserved.",
            nameof(LocalMode) => "Local mode",
            nameof(NormalMode) => "Ready",
            nameof(RuntimeMismatch) => "This profile is already open with another configuration/mode or is still starting. No new instance was created; the mode was not changed.",
            nameof(Starting) => "Starting isolated backend\u2026",
            nameof(AccessRevoked) => "Access revoked. Drafts remain in the window.",
            nameof(ActionFailed) => "The operation did not complete. The window is preserved; existing unrelated processes are not used.",
            nameof(RendererUnavailable) => "Renderer unavailable. Backend is preserved; restart only after checking drafts.",
            nameof(DrainPending) => "Backend is still shutting down. The window is preserved; closing can be retried.",
            nameof(RestartQuestion) => "Restart the backend and reopen the interface?",
            nameof(CloseQuestion) => "Close this window and stop only its backend?",
            nameof(SaveDrafts) => "Save or close drafts before continuing.\n",
            nameof(CheckUpdates) => "Check for updates",
            nameof(UpdateReady) => "Update {0} ready; installs after closing",
            nameof(UpToDate) => "You have the latest version.",
            nameof(UpdateCheckUnavailable) => "Could not check for updates now. The app will retry automatically.",
            _ => throw new System.ArgumentException("Unknown copy key", nameof(key))
        };
        return key switch
        {
            nameof(Recover) => Recover,
            nameof(Restart) => Restart,
            nameof(Revoke) => Revoke,
            nameof(BackendUnavailable) => BackendUnavailable,
            nameof(RecoveryReady) => RecoveryReady,
            nameof(LocalMode) => LocalMode,
            nameof(NormalMode) => NormalMode,
            nameof(RuntimeMismatch) => RuntimeMismatch,
            nameof(Starting) => Starting,
            nameof(AccessRevoked) => AccessRevoked,
            nameof(ActionFailed) => ActionFailed,
            nameof(RendererUnavailable) => RendererUnavailable,
            nameof(DrainPending) => DrainPending,
            nameof(RestartQuestion) => RestartQuestion,
            nameof(CloseQuestion) => CloseQuestion,
            nameof(SaveDrafts) => SaveDrafts,
            nameof(CheckUpdates) => CheckUpdates,
            nameof(UpdateReady) => UpdateReady,
            nameof(UpToDate) => UpToDate,
            nameof(UpdateCheckUnavailable) => UpdateCheckUnavailable,
            _ => throw new System.ArgumentException("Unknown copy key", nameof(key))
        };
